SELECT 'cart' AS src, SESSION_ID, CUSTOMER_ID FROM main.ABANDONED_CARTS LIMIT 3;
SELECT 'cart' AS src, CAST(SESSION_ID AS VARCHAR) AS sid, CAST(CUSTOMER_ID AS VARCHAR) AS cid FROM main.ABANDONED_CARTS LIMIT 3;
SELECT 'sess' AS src, CAST(SESSION_ID AS VARCHAR) AS sid, CAST(CUSTOMER_ID AS VARCHAR) AS cid, DURATION_SECONDS, PAGE_VIEWS, DEVICE_TYPE, UTM_SOURCE FROM main.WEB_SESSIONS LIMIT 3;
SELECT (SELECT count(*) FROM main.ABANDONED_CARTS c JOIN main.WEB_SESSIONS s ON CAST(c.SESSION_ID AS VARCHAR)=CAST(s.SESSION_ID AS VARCHAR)) AS joined_by_cast,
       (SELECT count(*) FROM main.ABANDONED_CARTS c JOIN main.WEB_SESSIONS s ON c.CUSTOMER_ID = s.CUSTOMER_ID) AS joined_by_customer,
       (SELECT count(*) FROM main.WEB_SESSIONS WHERE SESSION_ID IS NULL) AS sess_null;

